python3 << 'EOF'
import json

with open('batches/batch_0033.json', encoding='utf-8') as f:
    data = json.load(f)

MOJI_MARKERS = set('ãåæçèéªŸ¦¥½¡¿ºÀÌÎÍÔÖ¤¯Ó')

def looks_mojibake(s):
    if not s:
        return False
    return any(c in MOJI_MARKERS for c in s)

def decode_prefix(b, enc):
    """Try strict decode; on failure, truncate to the longest valid prefix and decode that."""
    try:
        return b.decode(enc)
    except UnicodeDecodeError as e:
        if e.start > len(b) * 0.5:  # only trust truncation near the end
            try:
                return b[:e.start].decode(enc)
            except UnicodeDecodeError:
                return None
        return None

def try_fix(s):
    if not s or not looks_mojibake(s):
        return s
    try:
        b = s.encode('latin1')
    except UnicodeEncodeError:
        return s
    for enc in ['utf-8', 'euc-jp', 'cp932']:
        fixed = decode_prefix(b, enc)
        if fixed:
            return fixed
    return s

fixed_count = 0
for item in data:
    for k in ['title','desc','body']:
        if k in item:
            orig = item[k]
            fixed = try_fix(orig)
            if fixed != orig:
                item[k] = fixed
                fixed_count += 1

print("fields fixed:", fixed_count)

with open('/tmp/fixed_batch_0033.json','w',encoding='utf-8') as f:
    json.dump(data, f, ensure_ascii=False, indent=1)
